// VEXORA API - QR code generator
// GET /api/qr?text=<any text or link>
// Returns: QR code image (image/png) - generated by our own code, no service.

const QRCode = require('qrcode');

module.exports = async (req, res) => {
  try {
    const { searchParams } = new URL(req.url, 'http://localhost');
    const text = (searchParams.get('text') || searchParams.get('q') || '').trim();
    if (!text) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ status: false, message: 'Missing ?text= parameter' }));
    }
    if (text.length > 800) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ status: false, message: 'Text is too long (max 800 characters)' }));
    }

    const buf = await QRCode.toBuffer(text, {
      type: 'png',
      width: 640,
      margin: 2,
      errorCorrectionLevel: 'M',
      color: { dark: '#0b0b10', light: '#ffffff' }
    });

    res.writeHead(200, { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=300' });
    res.end(buf);
  } catch (e) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: false, message: 'Server error: ' + e.message }));
  }
};
